<template><section><div class="title"><h1>搜索：{{wd}}</h1></div><VideoGrid :items="items"/><Pagination :page="page" :pages="pages" @change="go"/></section></template><script setup>import {ref,onMounted,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {searchVideos,normalizeList} from '../api/vod';import VideoGrid from '../components/VideoGrid.vue';import Pagination from '../components/Pagination.vue';const r=useRoute(),router=useRouter(),wd=ref(''),items=ref([]),page=ref(1),pages=ref(1);async function load(){wd.value=String(r.query.wd||'');page.value=Number(r.query.page||1);if(!wd.value)return;try{const x=await searchVideos(wd.value,page.value);items.value=normalizeList(x);pages.value=Number(x.pagecount||1)}catch{}}function go(n){router.push({query:{wd:wd.value,page:n}})}onMounted(load);watch(()=>[r.query.wd,r.query.page],load)</script>
